code='''def transform(grid):
    n = len(grid[0])
    center = next((i for i, v in enumerate(grid[0]) if v == 2), n // 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if r <= center and abs(c-center) == r:
                out[r][c] = 2
            elif (c-r) % 4 == center % 4 and (r > center or abs(c-center) < r):
                out[r][c] = 1
    return out
'''
open(p,'w').write(code); exec(code)
for n in [5,7,13]:
 x=[[0]*n];x[0][n//2]=2; print(transform(x))
